import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.BK-VYr1i.js";var i=JSON.parse(`{"title":"One No-Focus Contract for UI Operations","description":"","frontmatter":{"id":"policy.0003","title":"One No-Focus Contract for UI Operations","status":"active","established-by":"proposal.0005","supersedes":[]},"headers":[],"relativePath":"policies/0003-ui-no-focus.md","filePath":"policies/0003-ui-no-focus.md"}`),a={name:`policies/0003-ui-no-focus.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="one-no-focus-contract-for-ui-operations" tabindex="-1">One No-Focus Contract for UI Operations <a class="header-anchor" href="#one-no-focus-contract-for-ui-operations" aria-label="Permalink to “One No-Focus Contract for UI Operations”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Recon inspects applications on the Mac someone is using. Every mechanism it reaches for — accessibility, the window server, a loaded helper, a future UI action — has a shortcut available: bring the target forward, read what is now in front, and put things back. This policy settles that recurring decision once, for every <code>ui</code> operation, instead of leaving each backend to answer it.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>Once a request&#39;s prerequisites are established, no <code>ui</code> operation may activate or raise the target, transfer keyboard focus, make a window key, switch Spaces, move the real pointer, or divert input; an operation that observes such a disturbance must fail with <code>UI_INTERFERENCE</code> rather than restore what it saw change.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to “Why this exists”">​</a></h2><p>The behavior is unenforceable as an intention. &quot;Focus without raise&quot; still takes the keyboard away from whatever the user is typing into; activate-then-restore, a cursor moved and moved back, and a Space switched to reach a window all leave the desktop looking untouched once the command returns. The <a href="https://github.com/NSExceptional/winctl/blob/295a02751b2cb0c958b476e6ce6864963ee4042f/research/hittest/README.md" target="_blank" rel="noreferrer">winctl hittest research</a> that Recon&#39;s UI work derives from tested exactly those alternatives; they are plausible, they work, and they are indistinguishable from a clean read if the only evidence is the state before and after.</p><p>So the rule has a second half. A disturbance is a failed operation with observed effects, reported through <code>UI_INTERFERENCE</code> with its stage, evidence source, affected process and window, and whether target execution may continue. Taking focus back would be a second disturbance, and a quiet desktop at the end is not proof that the desktop was quiet throughout. Recon also does not blame what it cannot attribute: a change observed while the hardware was generating input belongs to the person at the keyboard, not to the target.</p><h2 id="what-it-applies-to" tabindex="-1">What it applies to <a class="header-anchor" href="#what-it-applies-to" aria-label="Permalink to “What it applies to”">​</a></h2><ul><li>Applies to: every operation reachable through <code>recon ui</code> — window inventory, <code>ui ax</code>, <code>ui view</code>, <code>ui session</code> lifecycle including background launch, screenshots, and <code>ui correlate</code> — together with the target-side work they dispatch, and the UI actions proposed in <a href="./../proposals/0005-native-macos-inspection">proposal 0005</a> issue #24. A supported action changes the target&#39;s own responder state; it still may not move the user&#39;s system focus.</li><li>Does not apply to: the setup prompts retained by <a href="./../decisions/0002-macos-context-privacy-identity">decision 0002</a>. A missing privacy grant may request macOS authorization and then fail with <code>PERMISSION_DENIED</code>, and <code>ui session open --mode attach --allow-authorization</code> may raise the debugger-authorization dialog. Those dialogs interrupt the desktop by design, which is why the no-interruption guarantee is conditional on prerequisites already being established. <code>recon app launch</code> is an explicitly activating command and is advertised as one.</li></ul><p>Neither exception authorizes activating a target to make an observation work, and a request whose prerequisites are present has no exception left to claim.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Tier: task (Tier 1), with structural enforcement in the implementation.</li><li>Mechanism: <code>crates/recon/src/macos/ui/focus.rs</code> watches the frontmost application, the order of the on-screen windows, the active Space, and the pointer and input event streams about every ten milliseconds, for the whole of every <code>ui</code> request, and turns an observed disturbance into <code>UI_INTERFERENCE</code> instead of a success. A dimension this Mac cannot report fails the operation with <code>INTERFACE_UNAVAILABLE</code> before it runs. <code>mise run check</code> runs the classification tests and the continuous-watch coverage test in <code>crates/recon/tests/ui_focus.rs</code>. <code>mise run test:focus</code> runs the live evidence out of process against the signed binary and the fixture; <code>cargo test -p recon --test ui_focus an_activating -- --ignored</code> exercises the counter-case, where an explicitly activating command must be visible to the same watch.</li><li>Prose justification: not applicable. The live evidence is a task rather than a check because it needs a logged-in Mac with the permissions granted to one signed executable and a desktop nobody is touching, which CI does not have; the in-process guard and its classification tests run unconditionally.</li></ul><h2 id="how-to-comply" tabindex="-1">How to comply <a class="header-anchor" href="#how-to-comply" aria-label="Permalink to “How to comply”">​</a></h2><ol><li>Reach macOS through the guarded path. A new <code>ui</code> operation runs inside <code>focus::guarded</code> with the stage and selected instance it is about; do not add a route that reaches the window server, accessibility, or a helper around it.</li><li>When a mechanism cannot do the requested work inside the boundary, report that with its typed reason — an unavailable interface or an unavailable inspection — rather than degrading to activation, a retry that takes focus, or an empty result presented as complete.</li><li>Run <code>mise run check</code>. For a change to a permission-gated or live path, also run <code>mise run test:focus</code> hands-off and record the evidence in the readiness report. Revise proposal intent before changing what the contract promises.</li></ol><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Proposal</th></tr></thead><tbody><tr><td>2026-10-28</td><td>Established the cross-command no-focus rule and its guard at completion.</td><td>proposal.0005</td></tr></tbody></table>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};